// NutriScanner — Confirmation & Final Calculation Engine
const body = $input.item.json.body || $input.item.json;
const confirmed = body.confirmed_data || body;

const serving = confirmed.serving || {};
const nutrition = confirmed.nutrition || {};
const ingredients = confirmed.ingredients || {};
const identity = confirmed.identity || {};
const allergens = confirmed.allergens || {};

// Deterministic Package Total Calculation
// Rule: Package Total = Nutrient Amount per Serving * Servings per Container
const servingsCount = (typeof serving.servings_per_container === 'number' && serving.servings_per_container > 0)
  ? serving.servings_per_container
  : null;

const calculatedPackage = {};
const canCalculatePackage = servingsCount !== null;

const standardNutrients = ['energy', 'protein', 'total_fat', 'saturated_fat', 'carbohydrate', 'sugar', 'sodium'];

for (const nutrient of standardNutrients) {
  const val = nutrition[nutrient];
  if (typeof val === 'number' && canCalculatePackage) {
    calculatedPackage[nutrient] = Math.round((val * servingsCount) * 100) / 100;
  } else {
    calculatedPackage[nutrient] = null;
  }
}

const missingInfo = confirmed.missing_information || [];
if (!canCalculatePackage) {
  missingInfo.push('Jumlah sajian per kemasan tidak tersedia; kalkulasi total kemasan ditiadakan.');
}

return [{
  json: {
    session_id: body.session_id || `nutri_${Date.now()}`,
    status: 'completed',
    result: {
      identity: identity,
      serving: serving,
      nutrition: nutrition,
      calculated: {
        package: calculatedPackage,
        can_calculate_package: canCalculatePackage
      },
      ingredients: ingredients,
      allergens: allergens,
      missing_information: missingInfo,
      neutral_summary: `Produk ${identity.name || ''} dengan takaran saji ${serving.size || '-'}${serving.unit || 'g'}.${typeof nutrition.energy === 'number' ? ` Energi ${nutrition.energy} kkal per sajian.` : ''}${canCalculatePackage && calculatedPackage.energy ? ` Total energi kemasan (${servingsCount} sajian) adalah ${calculatedPackage.energy} kkal.` : ''}`
    }
  }
}];
